import{_ as n,o as d,c,a2 as o}from"./chunks/framework.62rcL0wY.js";const l=JSON.parse('{"title":"Bảng thuật ngữ cố định","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/thuat-ngu.md","filePath":"phu-luc/thuat-ngu.md"}'),h={name:"phu-luc/thuat-ngu.md"};function e(r,t,g,i,a,s){return d(),c("div",null,[...t[0]||(t[0]=[o('<h1 id="bang-thuat-ngu-co-dinh" tabindex="-1">Bảng thuật ngữ cố định <a class="header-anchor" href="#bang-thuat-ngu-co-dinh" aria-label="Permalink to &quot;Bảng thuật ngữ cố định&quot;">​</a></h1><p>Trang này giải thích các thuật ngữ cố định được sử dụng thống nhất trong toàn bộ tài liệu Clickermann v4.13 tiếng Việt để người mới học dễ tra cứu.</p><h2 id="danh-sach-thuat-ngu" tabindex="-1">Danh sách thuật ngữ <a class="header-anchor" href="#danh-sach-thuat-ngu" aria-label="Permalink to &quot;Danh sách thuật ngữ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thuật ngữ trong tài liệu</th><th>Tên tiếng Anh / Ký hiệu</th><th>Giải thích ý nghĩa</th></tr></thead><tbody><tr><td><strong>Clickermann</strong></td><td>Clickermann</td><td>Tên chương trình tự động hóa (trong tài liệu này luôn gọi thống nhất là Clickermann, không gọi chung chung là &quot;tool&quot;)</td></tr><tr><td><strong>script</strong></td><td>Script (<code>.cms</code>)</td><td>Tệp kịch bản chứa danh sách các câu lệnh điều khiển Clickermann</td></tr><tr><td><strong>tệp</strong></td><td>File</td><td>Tệp tin lưu trên ổ đĩa (như tệp kịch bản <code>.cms</code>, tệp văn bản <code>.txt</code>, tệp cấu hình <code>.ini</code>, tệp ảnh <code>.bmp</code>)</td></tr><tr><td><strong>thư mục dự án</strong></td><td>Project Folder</td><td>Thư mục chứa tệp script <code>.cms</code> đang nạp; từ bản v4.6.000, mọi đường dẫn tệp tương đối trong script đều được tính từ thư mục này</td></tr><tr><td><strong><code>%Clickermann%</code></strong></td><td>Program Directory</td><td>Ký hiệu chỉ thư mục chương trình Clickermann (nơi chứa tệp chạy <code>.exe</code> và thư mục <code>data/</code>)</td></tr><tr><td><strong>nhật ký</strong></td><td>Log</td><td>Cửa sổ Nhật ký hoặc tệp nhật ký dùng để hiển thị/lưu các dòng thông báo xuất ra từ lệnh <a href="/clickermann-guide-vi/lenh/nhat-ky.html#logwrite-print"><code>PRINT</code></a> / <code>LOGWRITE</code></td></tr><tr><td><strong>thanh tác vụ</strong></td><td>Taskbar</td><td>Thanh tác vụ của Windows (nằm ở cạnh màn hình, nơi hiển thị biểu tượng các cửa sổ đang mở hoặc đang thu nhỏ)</td></tr><tr><td><strong>điểm ảnh</strong></td><td>Pixel</td><td>Một chấm màu nhỏ nhất tạo nên hình ảnh trên lưới màn hình, được xác định bởi tọa độ <code>(x, y)</code> và mã màu riêng</td></tr><tr><td><strong>bộ đệm ảnh</strong></td><td>Analysis Buffer</td><td>Vùng bộ nhớ lưu bức ảnh chụp màn hình từ lệnh <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a> để các lệnh đồ họa (<code>PXL</code>, <code>IF_PIXEL_IN</code>, <code>IF_PICTURE_IN</code>...) phân tích</td></tr><tr><td><strong>giảm màu</strong></td><td>Color Correction (<code>COLORMODE</code>)</td><td>Việc giảm bớt số lượng màu trong bộ đệm ảnh bằng lệnh <a href="/clickermann-guide-vi/lenh/man-hinh.html#colormode"><code>COLORMODE</code></a> để gom các sắc độ gần nhau về một màu đồng nhất</td></tr><tr><td><strong>kính lúp</strong></td><td>Magnifier</td><td>Công cụ phóng to vùng điểm ảnh dưới trỏ chuột ở góc dưới trái của <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a></td></tr><tr><td><strong>khóa cửa sổ, chế độ khóa cửa sổ</strong></td><td>Window Mode (<code>Alt + W</code>)</td><td>Chế độ gửi thông điệp thao tác riêng tới một cửa sổ/phần tử cụ thể mà không chiếm con trỏ chuột và bàn phím thật của người dùng</td></tr><tr><td><strong>phần tử đang khóa</strong></td><td>Target Element (<code>$_hwnd</code>)</td><td>Phần tử cửa sổ (xác định bởi mã <code>HWND</code>) đang được Clickermann khóa làm mục tiêu ở chế độ khóa cửa sổ</td></tr><tr><td><strong>phần tử con</strong></td><td>Child Window / Control</td><td>Các thành phần bên trong một cửa sổ ứng dụng (nút bấm, khung nhập, khung nội dung...), mỗi phần tử có mã <code>HWND</code> và hệ tọa độ tương đối riêng</td></tr><tr><td><strong><code>HWND</code></strong></td><td>Window Handle (<code>hwnd</code>)</td><td>Mã số định danh duy nhất mà hệ điều hành Windows cấp cho mỗi cửa sổ hoặc phần tử con đang mở</td></tr><tr><td><strong><code>PID</code></strong></td><td>Process ID (<code>pid</code>)</td><td>Mã số định danh tiến trình của một chương trình đang chạy trong Windows (xem được trên cửa sổ chính hoặc lấy qua <a href="/clickermann-guide-vi/lenh/winapi.html#hgetpid"><code>HGETPID</code></a>)</td></tr><tr><td><strong>thông điệp</strong></td><td>Windows Message</td><td>Tín hiệu điều khiển mà hệ điều hành Windows gửi tới cửa sổ hoặc phần tử (như thông điệp bấm chuột, gõ phím ở chế độ khóa cửa sổ hoặc thông điệp qua <a href="/clickermann-guide-vi/lenh/winapi.html#sendmessage-postmessage"><code>SENDMESSAGE</code></a>)</td></tr><tr><td><strong>thủ tục / hàm</strong></td><td>Procedure / Function</td><td><strong>Thủ tục</strong> là câu lệnh thực hiện hành động (như <code>LCLICK</code>); <strong>hàm</strong> là câu lệnh tính toán và trả về một giá trị ngay tại nơi gọi (như <code>RND</code>, <code>PXL</code>)</td></tr><tr><td><strong>tham số</strong></td><td>Parameter / Argument</td><td>Giá trị, biến hoặc biểu thức truyền vào bên trong cặp ngoặc tròn <code>( )</code> khi gọi một thủ tục hoặc hàm (ví dụ <code>100</code> và <code>200</code> trong <code>LCLICK(100, 200)</code>)</td></tr><tr><td><strong>biến</strong></td><td>Variable (<code>$var</code>)</td><td>Ô nhớ dùng để lưu dữ liệu (số hoặc chuỗi) trong lúc chạy script, tên luôn bắt đầu bằng dấu <code>$</code> (ví dụ <code>$dem</code>, <code>$x</code>)</td></tr><tr><td><strong>chuỗi</strong></td><td>String (<code>&quot;...&quot;</code>)</td><td>Dãy ký tự văn bản đặt trong cặp dấu ngoặc kép <code>&quot;...&quot;</code> (giữ nguyên nguyên văn, không bị tính toán như biểu thức số)</td></tr><tr><td><strong>mảng</strong></td><td>Array (<code>$arr[i]</code>)</td><td>Tập hợp các biến có chung tên, truy cập từng phần tử qua chỉ số nguyên trong ngoặc vuông (bắt đầu từ <code>0</code>)</td></tr><tr><td><strong>hằng</strong></td><td>Constant (<code>#CONST</code>)</td><td>Giá trị cố định không thay đổi trong lúc chạy, tên bắt đầu bằng dấu <code>#</code> và được nạp từ tệp <code>data/const.txt</code> (ví dụ <code>#SPACE</code>, <code>#ENTER</code>, <code>#TRUE</code>)</td></tr><tr><td><strong>nhãn</strong></td><td>Label (<code>ten_nhan:</code>)</td><td>Điểm đánh dấu dòng trong script (viết tên kèm dấu hai chấm <code>:</code>, đứng riêng một dòng) để lệnh <a href="/clickermann-guide-vi/lenh/kich-ban.html#goto"><code>GOTO</code></a> nhảy tới</td></tr><tr><td><strong>chương trình con (<code>SUB</code>)</strong></td><td>Subroutine (<code>SUB</code>)</td><td>Khối lệnh có tên riêng khai báo bằng <a href="/clickermann-guide-vi/lenh/cau-truc.html#sub-end-sub"><code>SUB ... END_SUB</code></a> ở bất kỳ đâu trong script nhưng phải nằm trước lời gọi</td></tr><tr><td><strong>luồng</strong></td><td>Thread (<code>THREAD</code>)</td><td>Chuỗi lệnh chạy song song độc lập với script chính, khai báo bằng <a href="/clickermann-guide-vi/lenh/cau-truc.html#thread-end-thread"><code>THREAD ... END_THREAD</code></a> và điều khiển qua <a href="/clickermann-guide-vi/lenh/cau-truc.html#setthread"><code>SETTHREAD</code></a></td></tr><tr><td><strong>chỉ thị</strong></td><td>Preprocessor Directive</td><td>Các lệnh tiền xử lý bắt đầu bằng dấu <code>#</code> (như <code>#name</code>, <code>#include</code>, <code>#logfile</code>, <code>#autorun</code>, <code>#define</code>), chỉ xử lý lúc nạp script</td></tr><tr><td><strong>phím tắt</strong></td><td>Hotkey</td><td>Tổ hợp phím điều khiển nhanh (như <code>Alt + A</code> chạy/tạm dừng, <code>Alt + S</code> dừng, <code>Alt + R</code> ghi, <code>Alt + W</code> khóa cửa sổ, <code>Alt + Q</code> chèn tọa độ, <code>Alt + G</code> chụp kính lúp)</td></tr><tr><td><strong><code>alt_winmode</code></strong></td><td>Alternative Windowed Mode (<code>alt_winmode.cms</code>)</td><td>Thư viện cộng đồng gồm các chương trình con <code>SUB</code> (<code>A_LCLICK</code>, <code>A_KEYPRESS</code>, <code>A_GETSCREEN</code>...) dùng <code>POSTMESSAGE</code> và <code>WNDGETINFO</code> để điều khiển nhiều cửa sổ theo từng <code>hwnd</code> riêng (không phải tính năng chính thức trong help — xem <a href="/clickermann-guide-vi/nang-cao/alt-winmode.html">Thư viện alt_winmode</a>)</td></tr></tbody></table>',4)])])}const m=n(h,[["render",e]]);export{l as __pageData,m as default};
